def solve(baseline,candidate,tolerance):
    delta=sum(b-a for a,b in zip(baseline,candidate))/len(baseline) if baseline else 0
    r=[i for i,(a,b) in enumerate(zip(baseline,candidate)) if b<a-tolerance]
    return {"meanDelta":delta,"regressions":r,"passes":not r and delta>=0}
